import fs from 'node:fs'
import path from 'node:path'

import { fileURLToPath } from 'node:url'

import yaml from 'yaml'

const __filename = fileURLToPath(import.meta.url)
const __dirname = path.dirname(__filename)

const localesDir = path.resolve(__dirname, '../packages/i18n/src/locales')
const outputDir = path.resolve(__dirname, '../packages/i18n/src/dist-lite') // Temporary location
if (!fs.existsSync(outputDir))
  fs.mkdirSync(outputDir, { recursive: true })

const allMessages = {}
const locales = fs.readdirSync(localesDir).filter(f => fs.statSync(path.join(localesDir, f)).isDirectory())

for (const locale of locales) {
  console.info(`Bundling ${locale}...`)
  const localeDir = path.join(localesDir, locale)

  // Custom logic for AIRI's nested structure
  const base = yaml.parse(fs.readFileSync(path.join(localeDir, 'base.yaml'), 'utf8'))
  const onboardingPath = path.join(localeDir, 'onboarding.yaml')
  const onboarding = fs.existsSync(onboardingPath)
    ? yaml.parse(fs.readFileSync(onboardingPath, 'utf8'))
    : {}
  const settings = yaml.parse(fs.readFileSync(path.join(localeDir, 'settings.yaml'), 'utf8'))
  const stage = yaml.parse(fs.readFileSync(path.join(localeDir, 'stage.yaml'), 'utf8'))

  const tamagotchiDir = path.join(localeDir, 'tamagotchi')
  const tamagotchiStage = yaml.parse(fs.readFileSync(path.join(tamagotchiDir, 'stage.yaml'), 'utf8'))
  const tamagotchiSettings = yaml.parse(fs.readFileSync(path.join(tamagotchiDir, 'settings.yaml'), 'utf8'))
  const tamagotchiTray = yaml.parse(fs.readFileSync(path.join(tamagotchiDir, 'electron', 'tray.yaml'), 'utf8'))

  allMessages[locale] = {
    base,
    onboarding,
    settings,
    stage,
    tamagotchi: {
      stage: tamagotchiStage,
      settings: tamagotchiSettings,
      electron: {
        tray: tamagotchiTray,
      },
    },
  }
}

const content = `// Auto-generated by scripts/bundle-i18n.js
const messages = ${JSON.stringify(allMessages, null, 2)}
messages['zh-CN'] = messages['zh-Hans']
messages['zh-TW'] = messages['zh-Hant']
export default messages
`
fs.writeFileSync(path.join(outputDir, 'messages.mjs'), content)
console.info('Bundle created at packages/i18n/src/dist-lite/messages.mjs')
